// C++11 Alias Template: clean and direct
template<typename T>
using MyAllocList = std::list<T, MyAlloc<T>>;

MyAllocList<int> list_cpp11; // Direct and intuitive usage

// C++98 Workaround: verbose and indirect
template<typename T>
struct MyAllocList_td {
  typedef std::list<T, MyAlloc<T>> type;
};

MyAllocList_td<int>::type list_cpp98; // Requires ::type suffix

// Using the C++98 workaround inside another template requires 'typename'
template<typename T>
class Widget {
  typename MyAllocList_td<T>::type data; // 'typename' is necessary here
  MyAllocList<T> data2; // Alias template is much cleaner
};
